"""Benign-floor re-score (review D2, N-01). Read-only re-analysis of existing data.

The shipped aggregators (e_c_write_time.py, e_ps_detection.py) count a trial's touched segment from one row only:
trial_row_ts(t), the second of the judged / forged / captured state row. A trial also wrote other rows: the
service-call event of its actuation (in the trial's own context, fired between the context's creation and the
state row) and every state row it edited. When those lie in another second, that second was counted "untouched",
and an edit could enter the benign floor.

NEW COUNTING RULE. A trial touches every one-second segment (and its minute) that holds a row the trial wrote:
  1. the second of trial_row_ts(t) (the old rule);
  2. the second of every state row it names (row_before, judged_row, forged_row, laundered_state_ids,
     swapped_state_ids), looked up in the snapshot;
  3. the second of every event that carries the trial's own context (row_before / forged_row context_id_bin) or a
     fabricated event context it minted (fabricated_event_context), read from the snapshot; when the trial deleted
     those events (laundering arms P, PU, PI), every second from the context's creation (its ULID timestamp) to the
     trial's state row, because the deleted service-call event fired inside that span;
  4. for the write-path hook (W3), whose state row carries a cover context, the adversary's residual service-call
     event (residual_adversary_call_service ts).
Everything else is the shipped verifier: first anchored root per segment among chain records whose payload ts lies
in [t_start, recorder_snapshot_at]; recompute with the shipped monitor's load()/commit() for the run's scheme;
segments whose start lies in [t_start - w, t_end + w]. The OLD rule is recomputed too, and must reproduce the
published floor exactly before the new one is reported.

Usage: floor_rescore.py TAG RESULT_JSON SNAPSHOT_DB CHAIN SCHEME
  CHAIN: a .jsonl or .jsonl.gz path, or container:<name> (read with docker exec cat)
  SCHEME: row | closure | wholerow
Writes exp/out/<TAG>_floor_rescore.json (never overwrites) and prints a one-line summary.
"""
import base64, collections, gzip, hashlib, importlib.util, json, os, subprocess, sys

TAG, RES, DB, CHAIN, SCHEME = sys.argv[1:6]
# The segment-window filter of verify_window ([t_start - w, t_end + w]) was not applied by the verifier that produced
# the earliest run (e_c_write_time, 2026-09-09): its published denominator (810) equals all roots anchored inside the
# time window minus the touched ones. "--no-segwin" reproduces that verifier; every other run uses the filter.
SEGWIN = "--no-segwin" not in sys.argv
REPO = "<artifact-root>"
OUT = os.path.join(REPO, "exp", "out")
dst = os.path.join(OUT, f"{TAG}_floor_rescore.json")
if os.path.exists(dst):
    raise SystemExit("refusing to overwrite " + dst)
os.environ["HOMEPROV_SCRATCH"] = os.path.dirname(DB)
if SCHEME == "wholerow":
    sys.path.insert(0, os.path.join(REPO, "monitor"))
    import monitor_wholerow as _wr
    M = _wr.M
else:
    os.environ["HOMEPROV_SCHEME"] = SCHEME
    spec = importlib.util.spec_from_file_location("mon_" + SCHEME, os.path.join(REPO, "monitor", "monitor.py"))
    M = importlib.util.module_from_spec(spec); spec.loader.exec_module(M)
W = dict(M.GRAN)
res = json.load(open(RES))
win = res["window"]
t0, t1, tsnap = win["t_start"], win["t_end"], win["recorder_snapshot_at"]
trials = [t for t in res["trials"] if t.get("arm") in ("PS", "PSR")] if "homeprov_detection_second" in res else res["trials"]

# ---------------------------------------------------------------- anchored roots (shipped rule)
if CHAIN.startswith("container:"):
    raw = subprocess.run(["docker", "exec", CHAIN.split(":", 1)[1], "cat", "/anchor/chain.jsonl"],
                         capture_output=True, text=True).stdout.splitlines()
elif CHAIN.endswith(".gz"):
    raw = gzip.open(CHAIN, "rt").read().splitlines()
else:
    raw = open(CHAIN).read().splitlines()
roots = {}
for line in raw:
    if not line.strip():
        continue
    try:
        rec = json.loads(line)
    except ValueError:
        continue
    p = rec.get("payload") or {}
    ts = p.get("ts") or rec.get("recv_ts") or 0.0
    if not (t0 <= ts <= tsnap) or p.get("evidence_unobservable"):
        continue
    for g, segs in (p.get("sealed") or {}).items():
        if g in W and isinstance(segs, dict):
            for s, v in segs.items():
                roots.setdefault((g, str(s)), v)

# ---------------------------------------------------------------- recompute (shipped load/commit)
since = (int(t0 // 3600) - 1) * 3600.0
phi = M.commit(M.load(DB, since=since))
verd = {}
for (g, s), a in roots.items():
    w = W[g]
    if SEGWIN and not (t0 - w <= int(s) * w <= t1 + w):
        continue
    got = (phi.get(g) or {}).get(s)
    if got is None:
        verd[(g, s)] = ("segment_vanished", None)
    elif got["acc"] != a["acc"] or got["n"] != a["n"]:
        dn = got["n"] - a["n"]
        verd[(g, s)] = ("rows_arrived_after_seal" if dn > 0 else "rows_removed_after_seal" if dn < 0
                        else "content_changed_in_place", dn)
    else:
        verd[(g, s)] = (None, 0)

# ---------------------------------------------------------------- touched sets
import sqlite3
con = sqlite3.connect(DB)
state_ts = lambda sid: (con.execute("SELECT last_updated_ts FROM states WHERE state_id=?", (sid,)).fetchone() or [None])[0]
B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"


def ulid_s(v):
    if not v:
        return None
    if len(v) == 32:                                   # context_id_bin as hex
        return int(v[:12], 16) / 1000.0
    if len(v) == 26:                                   # ULID string
        n = 0
        for ch in v[:10].upper():
            n = n * 32 + B32.index(ch)
        return n / 1000.0
    return None


def ulid_bytes(v):
    n = 0
    for ch in v.upper():
        n = n * 32 + B32.index(ch)
    return n.to_bytes(16, "big")


def row_ts(t):
    for k in ("judged_row", "forged_row", "row_before"):
        r = t.get(k)
        if isinstance(r, dict) and r.get("ts"):
            return float(r["ts"])
    return None


old = {g: set() for g in W}
new = {g: set() for g in W}
why_new = collections.defaultdict(list)
for t in trials:
    ts = row_ts(t)
    if ts is None:
        continue
    secs = {int(ts // 1)}
    old_s = int(ts // 1)
    for k in ("row_before", "judged_row", "forged_row"):
        r = t.get(k)
        if isinstance(r, dict) and r.get("state_id"):
            x = state_ts(r["state_id"]) or r.get("ts")
            if x:
                secs.add(int(float(x) // 1))
    for sid in (t.get("laundered_state_ids") or []) + (t.get("swapped_state_ids") or []):
        x = state_ts(sid)
        if x:
            secs.add(int(x // 1))
    if t.get("arm") == "W3":
        for e in t.get("residual_adversary_call_service") or []:
            if e.get("ts"):
                secs.add(int(float(e["ts"]) // 1))
    else:
        r = t.get("row_before") or t.get("forged_row") or t.get("judged_row") or {}
        for cid in (r.get("context_id_bin"), t.get("fabricated_event_context")):
            if not cid:
                continue
            b = bytes.fromhex(cid) if len(cid) == 32 else ulid_bytes(cid)
            evs = [x[0] for x in con.execute("SELECT time_fired_ts FROM events WHERE context_id_bin=?", (b,))]
            if evs:
                secs |= {int(x // 1) for x in evs if x}
            else:
                c = ulid_s(cid)
                if c is not None:
                    lo, hi = sorted((c, ts))
                    secs |= set(range(int(lo // 1), int(hi // 1) + 1))
    for s in secs:
        for g, w in W.items():
            seg = str(int(s * 1.0 // w))
            new[g].add(seg)
        if s != old_s:
            why_new[str(s)].append(f"{t.get('arm')}/{t.get('room')}/{t.get('trial')}")
    for g, w in W.items():
        old[g].add(str(int(ts // w)))


def floor(touched, g):
    segs = [s for (gg, s) in verd if gg == g and s not in touched]
    fails = [s for s in segs if verd[(g, s)][0]]
    mech = collections.Counter(verd[(g, s)][0] for s in fails)
    return {"k": len(fails), "n": len(segs), "mechanisms": dict(mech),
            "failing": [{"segment": s, "mechanism": verd[(g, s)][0], "delta_n": verd[(g, s)][1]} for s in sorted(fails)]}


fo = {g: floor(old[g], g) for g in ("second", "minute")}
fn = {g: floor(new[g], g) for g in ("second", "minute")}
pub = res["benign_violation_floor"]
reproduced = all((fo[g]["k"], fo[g]["n"]) == (pub[g]["k"], pub[g]["n"]) for g in ("second", "minute"))
moved = [{"segment": s, "mechanism": verd[("second", s)][0], "delta_n": verd[("second", s)][1],
          "touched_by": why_new.get(s, [])}
         for s in sorted({x["segment"] for x in fo["second"]["failing"]} - {x["segment"] for x in fn["second"]["failing"]})]
src = open(__file__).read()
fsha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest() if os.path.exists(p) else None
out = {"tag": TAG, "scheme": SCHEME, "result_file": os.path.relpath(RES, REPO),
       "snapshot_sha256": fsha(DB), "chain_sha256": fsha(CHAIN), "segment_window_filter": SEGWIN,
       "result_sha256": hashlib.sha256(open(RES, "rb").read()).hexdigest(),
       "snapshot": DB, "chain": CHAIN, "window": win,
       "published_floor": {g: {"k": pub[g]["k"], "n": pub[g]["n"]} for g in ("second", "minute")},
       "old_rule_floor": fo, "old_rule_reproduces_published": reproduced,
       "new_rule_floor": fn, "failures_moved_to_touched": moved,
       "newly_touched_second_segments": sorted(new["second"] - old["second"]),
       "rule": __doc__, "script_sha256": hashlib.sha256(src.encode()).hexdigest(), "script": src}
json.dump(out, open(dst, "w"), indent=1)
print(f"{TAG} {SCHEME}: published {pub['second']['k']}/{pub['second']['n']} old-rule {fo['second']['k']}/{fo['second']['n']} "
      f"(reproduced={reproduced}) new-rule {fn['second']['k']}/{fn['second']['n']} mech {fn['second']['mechanisms']} "
      f"minute {fo['minute']['k']}/{fo['minute']['n']}->{fn['minute']['k']}/{fn['minute']['n']} moved {moved}")
